SELECT 
 '/* ' + CONVERT(VARCHAR(20),RowNo) + ' */ ' + sqltext
FROM (

SELECT 
	ROW_NUMBER() OVER(ORDER BY c.custid ) AS RowNo,
	'DECLARE @ErrCode VARCHAR(300), @ErrMsg NVARCHAR(4000) '
	+ 'EXEC Acc_CustomerUpdMasterLiveCS_All'
	+ ' @custid =' + CONVERT(VARCHAR(20),c.custid)
	+ ', @srecommend = ' + CONVERT(VARCHAR(20),c.srecommend)
	+ ', @v162spositiontaking_1101 = 0'
	+ ', @v162mpositiontaking_1101 = ' + CONVERT(VARCHAR(20),mg.mpositiontaking)
	+ ', @auto_v162spositiontaking_1101 = ' + CONVERT(VARCHAR(20),sg.spositiontaking)
	+ ', @isauto_v162spositiontaking_1101 = 1'
	+ ', @v162mpositiontaking_1101_min = 0'
	+ ', @v162discount_1101 = 0'
	+ ', @v162UpdatePositiontaking_1101 = 1'
	+ ', @v162UpdateMinPositiontaking_1101 = 0'
	+ ', @v162UpdateAutoPositiontaking_1101 = 1'
	+ ', @v162UpdateCommission_1101 = 0'
	+ ', @SubAccID = 0'
	+ ', @IP=N''127.0.0.1'''
	+ ', @UserID = 5838421 /* dbaadmin */'
	+ ', @Language=N''E'''
	+ ', @updateallmembers = 0'
	+ ', @newspositiontaking = 0'	
	+ ', @ErrCode = @ErrCode OUTPUT'
	+ ', @ErrMsg = @ErrMsg OUTPUT'
	+ ' SELECT @ErrCode,@ErrMsg '
	+ ' dddGO ' as sqltext
FROM custInfo c WITH(NOLOCK)
	INNER JOIN CustSettingGame mg WITH(NOLOCK) ON c.custid = mg.CustID
	INNER JOIN CustSettingGame sg WITH(NOLOCK) ON c.srecommend = sg.CustID
WHERE c.srecommend IN (395075,727340,394310,726562,674248,194355,391601,913628,1069029,2400612)
AND mg.autopositiontaking <> sg.spositiontaking
AND roleid = 3
AND Enabled = 1
) t